def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    difference = v1 - v2
    return {
        "value": round(difference),
        "trace": {
            "v1": v1,
            "v2": v2,
            "difference": difference,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
